import { NextResponse } from "next/server";
import { Prisma } from "@prisma/client";
import { z } from "zod";
import prisma from "@/lib/prisma";
import { parseJson, route } from "@/lib/api/http";
import { requireAdmin } from "@/lib/auth/session";
import { JOB_FORM_FIELD_MAP, TRANSACTION_FIELD_MAP } from "@/lib/forms/fieldMap";

const bodySchema = z.object({
  formKey: z.string().min(1).max(64),
  // Ids are generated by the builder; the pattern keeps LIKE wildcards out of the query.
  fieldId: z.string().regex(/^[A-Za-z0-9_-]{1,100}$/),
});

// The id as a JSON key: `"id"` at the top level, or `\"id\"` inside repeatable entries, which are stored as JSON strings.
const jsonKeyPattern = (key: string) => `${key}\\\\?"`;

/**
 * How many live records hold a value for a layout field. Values live in `customData` under the field id
 * (also inside repeatable entries, which are stored as JSON strings), or in a first-class column for the
 * built-in fields, which every record has.
 */
async function countFieldUsage(formKey: string, fieldId: string): Promise<number> {
  if (formKey === "JOB_FORM") {
    if (JOB_FORM_FIELD_MAP[fieldId]) return prisma.job.count({ where: { deletedAt: null } });
    const rows = await prisma.$queryRaw<{ count: bigint }[]>(
      Prisma.sql`SELECT COUNT(*)::bigint AS count FROM "Job" WHERE "deletedAt" IS NULL AND "customData"::text ~ ${jsonKeyPattern(fieldId)}`
    );
    return Number(rows[0]?.count ?? 0);
  }
  if (formKey === "TRANSACTION_FORM") {
    if (TRANSACTION_FIELD_MAP[fieldId]) return prisma.transaction.count({ where: { deletedAt: null } });
    const rows = await prisma.$queryRaw<{ count: bigint }[]>(
      Prisma.sql`SELECT COUNT(*)::bigint AS count FROM "Transaction" WHERE "deletedAt" IS NULL AND "customData"::text ~ ${jsonKeyPattern(fieldId)}`
    );
    return Number(rows[0]?.count ?? 0);
  }
  return 0;
}

export const POST = route(async (req) => {
  await requireAdmin();
  const { formKey, fieldId } = await parseJson(req, bodySchema);
  const count = await countFieldUsage(formKey, fieldId);
  return NextResponse.json({ count });
});
